/**
 * Subsetted DejaVu Sans for simulation map SVG @font-face.
 * Latin + Spanish accents (áéíóúñ…) so sharp/librsvg can render text on Vercel
 * without reading fonts from disk.
 * Original: lib/sim-report/fonts/DejaVuSans.ttf → subset 52920 bytes.
 */
export const MAP_FONT_FAMILY = 'SimReportSans'

export const MAP_FONT_TTF_BASE64 =
  ''

/** CSS @font-face block to inject into the map SVG <defs>. */
export function mapFontFaceCss(): string {
  return (
    `@font-face{font-family:'${MAP_FONT_FAMILY}';` +
    `src:url('data:font/ttf;base64,${MAP_FONT_TTF_BASE64}') format('truetype');` +
    `font-weight:400;font-style:normal;}`
  )
}
